// The only place to configure the bot.
const ALLOWED_CHAT_IDS = [];                 // TODO: chat ids allowed to query the vault
const SUPABASE_URL = '';                     // TODO: https://<project>.supabase.co
const EMBEDDING_MODEL = 'text-embedding-3-small';
const TOP_K = 8;

if (!ALLOWED_CHAT_IDS.length) throw new Error('ALLOWED_CHAT_IDS is empty in "Config"');
if (!SUPABASE_URL) throw new Error('SUPABASE_URL is not configured in "Config"');

const msg = $input.first().json || {};
const message = msg.message || msg;
const chatId = String(message.chat && message.chat.id ? message.chat.id : '');
const question = String(message.text || '').trim();

const base = SUPABASE_URL.replace(/\/+$/, '');
return [{
  json: {
    chatId,
    question,
    // The vault is personal. Anyone who can reach the bot must be on the list, and the
    // check happens before the question is embedded or the vault is searched.
    allowed: ALLOWED_CHAT_IDS.map(String).includes(chatId) && question.length > 0,
    topK: TOP_K,
    embeddingModel: EMBEDDING_MODEL,
    embeddingsUrl: 'https://api.openai.com/v1/embeddings',
    matchUrl: base + '/rest/v1/rpc/match_vault_chunks',
    body: { model: EMBEDDING_MODEL, input: [question] },
  },
}];

// Turns the question embedding into a search call.
const res = $input.first().json || {};
const cfg = $('Config').first().json;

const vector = res.data && res.data[0] ? res.data[0].embedding : null;
if (!Array.isArray(vector)) throw new Error('embedding request returned no vector');

return [{
  json: {
    ...cfg,
    searchBody: { query_embedding: vector, match_count: cfg.topK },
  },
}];

// Builds the answer request. The instruction to admit ignorance is not decoration: a
// vault question with no matching note must produce "I do not know", not a plausible
// paragraph assembled from unrelated chunks.
const cfg = $('Prepare search').first().json;
const matches = $input.all().map((i) => i.json).filter((m) => m && m.content);

const context = matches.map((m, i) => [
  '[' + (i + 1) + '] ' + m.path + (m.heading ? ' > ' + m.heading : ''),
  m.content,
].join('\n')).join('\n\n---\n\n');

return [{
  json: {
    ...cfg,
    matches,
    matchCount: matches.length,
    system: 'You answer questions using only the notes provided. If the notes do not'
      + ' contain the answer, say so plainly and do not guess. Never use knowledge from'
      + ' outside the provided notes.',
    user: 'Question: ' + cfg.question
      + '\n\nNotes:\n\n' + (context || '(no notes matched)')
      + '\n\nAnswer from these notes only. List the notes you used by their path.',
    max_retries: 2,
    schema: {
      type: 'object',
      required: ['answer', 'used_paths', 'enough_context'],
      properties: {
        answer: { type: 'string' },
        used_paths: { type: 'array', items: { type: 'string' } },
        enough_context: { type: 'boolean' },
      },
    },
  },
}];

// Formats the reply. Sources are taken from what the search actually returned and the
// model said it used, never from the model alone, so a path cannot be invented.
const llm = $input.first().json || {};
const state = $('Build answer request').first().json;

const esc = (s) => String(s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const known = new Set(state.matches.map((m) => m.path));
const claimed = llm.ok && llm.data && Array.isArray(llm.data.used_paths) ? llm.data.used_paths : [];
const used = [...new Set(claimed.filter((p) => known.has(p)))];
const invented = claimed.filter((p) => !known.has(p)).length;

let text;
if (!llm.ok) {
  text = 'I could not get an answer just now. Try again in a moment.';
} else if (!state.matchCount || llm.data.enough_context === false) {
  text = esc(llm.data && llm.data.answer ? llm.data.answer : 'I do not know: nothing in the vault covers that.');
} else {
  const body = esc(llm.data.answer || '').trim();
  const sources = used.length
    ? '\n\n<b>Notes used</b>\n' + used.map((p) => '• ' + esc(p)).join('\n')
    : '\n\n<i>No note could be credited for this answer.</i>';
  text = body + sources;
}

return [{
  json: {
    text,
    chatId: state.chatId,
    used,
    inventedPaths: invented,
    matchCount: state.matchCount,
    answered: Boolean(llm.ok && state.matchCount && llm.data && llm.data.enough_context !== false),
  },
}];
